#   e.g. when a user uploads a file but deletes it before the analysis runs.
# Avoids `Aws::S3::Errors::NoSuchKey` when an upload is deleted before AnalyzeJob runs.
module ActiveStorageAnalyzeJobSkipDetached
  def perform(blob)
